// Inventory and stock movements.
// Owner: Agent B2 (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { isoDate, minor, optionalPhone, optionalText, text, uuid } from './common';

export const inventoryContractsVersion = 1 as const;

export const INVENTORY_UNITS = ['g', 'kg', 'ml', 'l', 'pcs'] as const;
export const inventoryUnit = z.enum(INVENTORY_UNITS);
export type InventoryUnit = (typeof INVENTORY_UNITS)[number];

/** Units convert only inside one family (mass, volume, count). */
const UNIT_FACTORS: Record<InventoryUnit, { family: 'mass' | 'volume' | 'count'; factor: number }> = {
  g: { family: 'mass', factor: 1 }, kg: { family: 'mass', factor: 1000 },
  ml: { family: 'volume', factor: 1 }, l: { family: 'volume', factor: 1000 },
  pcs: { family: 'count', factor: 1 },
};
export const unitFamily = (u: InventoryUnit) => UNIT_FACTORS[u].family;
export const unitsCompatible = (a: InventoryUnit, b: InventoryUnit) => UNIT_FACTORS[a].family === UNIT_FACTORS[b].family;

/** Converts a quantity between compatible units, rounded to 3 decimals (the storage precision). */
export function convertQuantity(quantity: number, from: InventoryUnit, to: InventoryUnit): number {
  if (!unitsCompatible(from, to)) throw new RangeError(`Cannot convert ${from} to ${to}`);
  return Math.round((quantity * UNIT_FACTORS[from].factor / UNIT_FACTORS[to].factor) * 1000) / 1000;
}

/** Positive quantity with at most 3 decimals (numeric(14,3) in the database). */
export const quantity = z.number().positive().max(1e9).refine((n) => Math.abs(Math.round(n * 1000) - n * 1000) < 1e-6, 'at most 3 decimals');
export const nonNegativeQuantity = z.number().min(0).max(1e9).refine((n) => Math.abs(Math.round(n * 1000) - n * 1000) < 1e-6, 'at most 3 decimals');
const signedQuantity = z.number().min(-1e9).max(1e9).refine((n) => n !== 0, 'must not be zero')
  .refine((n) => Math.abs(Math.round(n * 1000) - n * 1000) < 1e-6, 'at most 3 decimals');

export const supplierInput = z.object({
  name: text(120),
  phone: optionalPhone(30),
  email: z.email().max(200).optional().nullable(),
  notes: optionalText(500),
});
export const supplierUpdate = supplierInput.partial();
export type SupplierInput = z.infer<typeof supplierInput>;

export const inventoryItemInput = z.object({
  name: text(120),
  nameAr: optionalText(120),
  sku: optionalText(60),
  unit: inventoryUnit,
  /** Minor units per one `unit` (e.g. piastres per kg). Use kg/l for cheap bulk ingredients. */
  costPerUnitMinor: minor,
  reorderLevel: nonNegativeQuantity.default(0),
  supplierId: uuid.optional().nullable(),
});
export const inventoryItemUpdate = inventoryItemInput.omit({ unit: true }).partial().extend({ isActive: z.boolean().optional() });
export type InventoryItemInput = z.infer<typeof inventoryItemInput>;

export const WASTE_REASONS = ['expired', 'spoiled', 'damaged', 'overproduction', 'plate_waste', 'other'] as const;
export const wasteReason = z.enum(WASTE_REASONS);

const movementBase = { itemId: uuid, note: optionalText(300) };
/** Quantities may be entered in any unit compatible with the item's unit; the API converts. */
export const stockMovementInput = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('purchase'), branchId: uuid, ...movementBase, quantity, unit: inventoryUnit.optional(),
    /** Cost per item unit paid on this purchase; updates the item's current cost unless keepItemCost. */
    unitCostMinor: minor.optional(), supplierId: uuid.optional().nullable(), keepItemCost: z.boolean().optional() }),
  z.object({ kind: z.literal('waste'), branchId: uuid, ...movementBase, quantity, unit: inventoryUnit.optional(), reason: wasteReason }),
  z.object({ kind: z.literal('adjustment'), branchId: uuid, ...movementBase, quantityDelta: signedQuantity, unit: inventoryUnit.optional() }),
  z.object({ kind: z.literal('transfer'), fromBranchId: uuid, toBranchId: uuid, ...movementBase, quantity, unit: inventoryUnit.optional() })
    .refine((v) => v.fromBranchId !== v.toBranchId, { message: 'choose two different branches', path: ['toBranchId'] }),
  z.object({ kind: z.literal('count'), branchId: uuid, ...movementBase, countedQuantity: nonNegativeQuantity, unit: inventoryUnit.optional() }),
]);
export type StockMovementInput = z.infer<typeof stockMovementInput>;

/** Stocktake of several items at once (each line behaves like a 'count' movement). */
export const stocktakeInput = z.object({
  branchId: uuid,
  lines: z.array(z.object({ itemId: uuid, countedQuantity: nonNegativeQuantity, unit: inventoryUnit.optional(), note: optionalText(300) })).min(1).max(500),
});

export const recipeInput = z.object({
  components: z.array(z.object({ itemId: uuid, quantity, unit: inventoryUnit })).max(100)
    .refine((c) => new Set(c.map((x) => x.itemId)).size === c.length, 'each item may appear once'),
});
export type RecipeInput = z.infer<typeof recipeInput>;

export const movementListQuery = z.object({
  branchId: uuid.optional(),
  itemId: uuid.optional(),
  reason: z.enum(['purchase', 'sale', 'waste', 'adjustment', 'transfer_in', 'transfer_out', 'count', 'return']).optional(),
  from: isoDate.optional(),
  to: isoDate.optional(),
  limit: z.coerce.number().int().min(1).max(200).default(50),
  cursor: z.string().regex(/^\d+$/).optional(),
});

export const wasteReportQuery = z.object({ from: isoDate, to: isoDate, branchId: uuid.optional() });

export interface InventoryItemView {
  id: string; name: string; nameAr: string | null; sku: string | null; unit: InventoryUnit;
  costPerUnitMinor: number; reorderLevel: number; supplierId: string | null; supplierName: string | null; isActive: boolean;
  totalQuantity: number;
}
export interface StockLevelView {
  itemId: string; name: string; nameAr: string | null; unit: InventoryUnit; branchId: string; quantity: number;
  reorderLevel: number; costPerUnitMinor: number; valueMinor: number; low: boolean; lastCountedAt: string | null;
}
export interface StockMovementView {
  id: string; branchId: string; itemId: string; itemName: string; unit: InventoryUnit; quantityDelta: number; reason: string;
  wasteReason: string | null; unitCostMinor: number | null; referenceType: string | null; referenceId: string | null;
  note: string | null; actorId: string | null; createdAt: string;
}
